CREATE TABLE `members_source` (
  `id` int NOT NULL AUTO_INCREMENT,
  `member_id` varchar(20) NOT NULL,
  `user_type_id` int DEFAULT NULL,
  `gotra` varchar(100) DEFAULT NULL,
  `family_name` varchar(100) DEFAULT NULL,
  `public_id` varchar(36) NOT NULL,
  `name` varchar(100) NOT NULL,
  `father_name` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `whatsapp` varchar(15) DEFAULT NULL,
  `blood_group` varchar(5) DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `out_of_rajapalayam` tinyint(1) DEFAULT '0',
  `address_id` int DEFAULT NULL,
  `outside_address_id` int DEFAULT NULL,
  `address_proof_id` int DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `email` varchar(100) DEFAULT NULL,
  `address` text,
  `photo` varchar(255) DEFAULT NULL,
  `membership_type` varchar(50) DEFAULT NULL,
  `join_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `status` enum('Active','Inactive','Expired') DEFAULT 'Active',
  `payment_status` enum('Paid','Unpaid') DEFAULT 'Unpaid',
  `deactivation_reason` text,
  `qr_code_path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `branch` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `member_id` (`member_id`),
  UNIQUE KEY `public_id` (`public_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1010 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
